// render.tsx — the hooks module: a ```dot or ```svg fence
// drawn on every screen Claude Code draws a reply on, and a list drawn with rails — a dim
// vertical at each level's marker column, so a wrapped item's lines say
// which marker they hang from.
//
// The MessageDisplay hook is asked about the live turn of the main thread
// and nothing else. A fork's view, a subagent's, a transcript replayed by
// --resume and a background job reattached are drawn from the transcript,
// and no display hook is asked about them — measured on 2.1.283, each of
// them showed the fence as source. ui.render is asked about every
// assistant text block on every one of those screens.
//
// Where the display hook has drawn — the main thread's own turn — this
// hook is handed the drawing, not the fence (measured: the text it gets is
// the hook's output), finds no fence in it, and hands the block on
// untouched. In a background job forced to draw Images the display hook
// draws nothing and hands every delta on as it arrived (drawer's
// hookForm), and this hook draws the live turn too, as it streams, an
// unclosed fence included. Either way one of the two draws a fence and
// the other passes it.
//
// A block with a graph in it is cut at its fences. The prose between them
// is Claude Code's own drawing (next, with the text cut to that stretch);
// each fence is what `drawer -element` makes of it: an Image wherever
// Claude Code draws one; Text rows of box drawing where it draws none —
// behind tmux, screen or mosh, and in a background job no Image reaches
// (drawer's elementForm); and Text rows of a notice over the source where
// the picture fails. Anything that fails here leaves the block to Claude
// Code as it arrived.
//
// Function hooks are early access. A build that does not load hooks
// modules runs the command hooks in hooks.json alone, and there they are
// the whole plugin.

import type { Elements, EngineInterface, Register, RenderChildren } from 'claude-code'

// The fence rules are internal/fence's, for a block that has arrived
// whole: a run of three or more backticks or tildes at the start of a
// line, closed by a run of the same character at least as long with
// nothing else on the line. A fence labelled dot or graphviz is a graph's;
// an unlabelled one is when its first line opens a graph; one labelled
// svg is an SVG picture; any other is somebody else's, and a ```dot
// quoted inside it is text.
//
// They are Go's character for character. A space is unicode.IsSpace's,
// which strings.TrimSpace and strings.Fields cut at, and not JavaScript's
// \s or trim(): U+0085 is one, U+FEFF is not. RE2's . is anything but a
// newline, and its \s and \b are ASCII; its (?i) folds by Unicode's simple
// folding, so ſ is an s, which /iu does too, in a class as well: the word
// boundary after graph is read apart, without the flag. strings.ToLower
// makes İ an i.
const space = '\\t\\n\\v\\f\\r \\u0085\\u00a0\\u1680\\u2000-\\u200a\\u2028\\u2029\\u202f\\u205f\\u3000'
const edgeSpace = new RegExp(`^[${space}]+|[${space}]+$`, 'g')
const spaces = new RegExp(`[${space}]+`)
const fenceRe = /^([ \t]*)(`{3,}|~{3,})([^\n]*)$/
const graphKeyword = /^[\t\n\f\r ]*(strict[\t\n\f\r ]+)?(di)?graph/iu
const graphRest = /^(?![0-9A-Za-z_])[^{]*\{/

const trimSpace = (s: string) => s.replace(edgeSpace, '')

// graphStart is a DOT graph's first line: the keyword, a name if any, and
// the brace.
function graphStart(line: string) {
  const m = graphKeyword.exec(line)
  return m !== null && graphRest.test(line.slice(m[0].length))
}

type Opener = { indent: string; run: string; info: string }

function openerOf(line: string): Opener | null {
  const m = fenceRe.exec(line.replace(/[ \t\r]+$/, ''))
  if (!m) return null
  const [, indent = '', run = '', rest = ''] = m
  if (run[0] === '`' && rest.includes('`')) return null
  const info = (trimSpace(rest).split(spaces)[0] ?? '').replace(/İ/g, 'i').toLowerCase()
  return { indent, run, info }
}

function closes(f: Opener, line: string) {
  const t = trimSpace(line)
  return t.length >= f.run.length && [...t].every((c) => c === f.run[0])
}

// columnsOf is an indent's width as the display hook measures it,
// grid.Cells: a space is a column and a tab is none.
function columnsOf(indent: string) {
  return [...indent].filter((c) => c === ' ').length
}

// A stretch of a block: prose, or a picture's fence with its source cut
// out and the language it is in (drawer's Opener.Tag).
type Tag = 'dot' | 'svg'
type Part = { raw: string; src?: string; tag?: Tag; indent?: number; closed?: boolean }

function tagOf(info: string): Tag {
  return info === 'svg' ? 'svg' : 'dot'
}

// split cuts a block into stretches of prose and graphs, by line. Every
// stretch keeps its lines exactly as they arrived, so a graph that will
// not draw goes back into the prose around it byte for byte.
function split(text: string): Part[] {
  const lines = text.split('\n')
  const parts: Part[] = []
  let prose = 0
  for (let i = 0; i < lines.length; ) {
    const f = openerOf(lines[i] ?? '')
    if (!f) {
      i++
      continue
    }
    let j = i + 1
    while (j < lines.length && !closes(f, lines[j] ?? '')) j++
    const closed = j < lines.length
    const body = lines
      .slice(i + 1, j)
      .map((l) => (l.startsWith(f.indent) ? l.slice(f.indent.length) : l))
      .join('\n')
    const first = body.split('\n').find((l) => trimSpace(l) !== '') ?? ''
    const ours =
      f.info === 'dot' || f.info === 'graphviz' || f.info === 'svg' || (f.info === '' && graphStart(trimSpace(first)))
    const end = closed ? j + 1 : lines.length
    if (ours) {
      if (i > prose) parts.push({ raw: lines.slice(prose, i).join('\n') })
      parts.push({ raw: lines.slice(i, end).join('\n'), src: body, tag: tagOf(f.info), indent: columnsOf(f.indent), closed })
      prose = end
    }
    i = end
  }
  if (prose < lines.length) parts.push({ raw: lines.slice(prose).join('\n') })
  return parts
}

// A span is a run of one style in a row of glyphs. The first three are
// the wall's; bold, italic, strikethrough and a link's address are the
// list door's, read out of an item's inline markdown.
type Span = { t: string; c?: string; d?: boolean; b?: boolean; i?: boolean; s?: boolean; href?: string }

// Drawing is what `drawer element` answers for one fence: a picture, rows
// of text (a row with none is blank) — box drawing, or a notice that says
// why there is no picture, over the source — or none, the fence left as it
// arrived. failed is a run that answered nothing, which is asked again.
// viewers is an answer picked for whoever watches a background job now
// (drawer's elementForm), which is asked again once it is viewersMs old.
type Drawing = (
  | { kind: 'image'; png: string; columns: number; rows: number; alt?: string; notice?: boolean }
  | { kind: 'text'; lines: (Span[] | null)[]; notice?: boolean }
  | { kind: 'none'; failed?: boolean; notice?: undefined }
) & { viewers?: boolean }

// The drawings this module has asked for, newest last: a block is drawn
// again on every scroll that moves it past an edge of the screen, and on
// every width, and the answer does not change between them — but in a
// background job forced to draw Images, where it is an Image for the
// windows it reaches and box drawing while one watches from behind tmux,
// screen or mosh, and the windows come and go for as long as this worker
// runs. That answer is kept viewersMs, one burst of renders, so a render
// after a window came or went asks for that window. A window attaching is
// not one: measured 2026-10-08, Claude Code 2.1.293, a fresh `claude
// attach` 67 s after the reply asked this module nothing and was sent the
// Image drawn before. The theme is in the key, because a picture is
// painted in it, and so is the indent, because the drawing is as wide as
// the screen less it, and so is the tag, because the same text is another
// picture in another language.
const drawn = new Map<string, { p: Promise<Drawing>; until: number }>()
const drawnMost = 48
const viewersMs = 1000

function drawOnce($: EngineInterface, src: string, cols: number, indent: number, theme: string, door: 'element' | 'list' = 'element', tag: Tag = 'dot') {
  const key = `${door}\u0000${tag}\u0000${theme}\u0000${cols}\u0000${indent}\u0000${src}`
  const had = drawn.get(key)
  if (had && Date.now() < had.until) {
    drawn.delete(key)
    drawn.set(key, had)
    return had.p
  }
  const entry = { p: drawElement($, src, cols, indent, door, tag), until: Infinity }
  entry.p = entry.p.then((el) => {
    if (el.kind === 'none' && el.failed && drawn.get(key) === entry) drawn.delete(key)
    if (el.viewers) entry.until = Date.now() + viewersMs
    return el
  })
  drawn.delete(key)
  drawn.set(key, entry)
  const oldest = drawn.keys().next().value
  if (drawn.size > drawnMost && oldest !== undefined) drawn.delete(oldest)
  return entry.p
}

// drawElement runs the binary on one fence. A run that fails is failed,
// and asked again on the next render: the wrapper exits non-zero where it
// finds no binary, which the next session start puts in place. A run past
// runMs is killed by the engine, which rejects with "still running after";
// that is a layout too slow to wait for, and it is a none for the session.
// A fence that is not a graph's names its language last; a graph's names
// none, which the wrapper reads as dot.
const runMs = 15000

async function drawElement($: EngineInterface, src: string, cols: number, indent: number, door: 'element' | 'list' = 'element', tag: Tag = 'dot'): Promise<Drawing> {
  const argv = [`${$.plugin.root}/scripts/drawer`, door, String(cols), String(indent)]
  if (door === 'element' && tag !== 'dot') argv.push(tag)
  try {
    const { exitCode, stdout } = await $.process.run(argv, { stdin: src, timeoutMs: runMs })
    if (exitCode !== 0) return { kind: 'none', failed: true }
    return JSON.parse(stdout) as Drawing
  } catch (err) {
    const said = typeof err === 'object' && err !== null && 'message' in err ? String(err.message) : String(err)
    return /still running after/.test(said) ? { kind: 'none' } : { kind: 'none', failed: true }
  }
}

// ---- lists ----
//
// A list in the prose is drawn with rails: a hairline at each level's
// marker column, so a wrapped item's lines say which marker they hang
// from. The rows come from the binary's -list door — wrapped and styled
// by the same hand that draws the rail, so the rail stands on every row
// by construction — and a span carrying a link's address is drawn as a
// Link, clickable where the terminal clicks. A picture inside an item
// breaks its rail for its own rows and the rail resumes under it.
//
// A hairline needs the row count, and the row count belongs to whoever
// wraps: the engine validates element props against an allowlist
// (measured on 2.1.295) with none of the per-side borders its own quote
// rail is drawn with, nothing else a plugin draws stretches to a height
// it does not know, and Claude Code wraps after this hook has answered.
// So the door wraps. Where there is no door — an older binary, or none —
// the level falls back to the one stretch the engine does give a plugin:
// a width-1 Box behind the engine's own Markdown, its background the
// theme's user-message background (railsBlock).
//
// The cut is by line and fence-aware both ways: a fence inside an item
// stays inside its item, and a marker inside any fence is code.

const markerRe = /^( *)(?:[-*+]|\d{1,9}[.)])( |$)/
const anyMarker = new RegExp(markerRe.source, 'm')

// markerIndentOf is the marker's column where a line opens a list item,
// and null where it does not.
function markerIndentOf(line: string): number | null {
  const m = markerRe.exec(line)
  return m ? (m[1] ?? '').length : null
}

function leadingSpaces(line: string): number {
  let n = 0
  while (line[n] === ' ') n++
  return n
}

// A piece of a prose stretch: prose, or a list block kept as its lines.
type Piece = { prose: string } | { list: string[] }

// cutLists cuts one prose stretch at its lists. A block opens at a marker
// and holds further markers, continuation lines indented two or more,
// fences indented into an item, and blank lines a later list line
// reclaims. Anything else ends it. A fence at the margin is prose with
// whatever markers it quotes.
function cutLists(text: string): Piece[] {
  const lines = text.split('\n')
  const pieces: Piece[] = []
  let plain = 0
  const fenceEnd = (from: number): number => {
    const f = openerOf(lines[from] ?? '')
    if (!f) return from + 1
    let k = from + 1
    while (k < lines.length && !closes(f, lines[k] ?? '')) k++
    return k < lines.length ? k + 1 : lines.length
  }
  for (let i = 0; i < lines.length; ) {
    if (openerOf(lines[i] ?? '')) {
      i = fenceEnd(i)
      continue
    }
    if (markerIndentOf(lines[i] ?? '') === null) {
      i++
      continue
    }
    let end = i + 1
    for (let j = i + 1; j < lines.length; ) {
      const l = lines[j] ?? ''
      if (openerOf(l) && leadingSpaces(l) >= 2) {
        j = end = fenceEnd(j)
        continue
      }
      if (trimSpace(l) === '') {
        j++
        continue
      }
      if (markerIndentOf(l) === null && leadingSpaces(l) < 2) break
      end = ++j
    }
    if (i > plain) pieces.push({ prose: lines.slice(plain, i).join('\n') })
    pieces.push({ list: lines.slice(i, end) })
    plain = i = end
  }
  if (plain < lines.length) pieces.push({ prose: lines.slice(plain).join('\n') })
  return pieces
}

// The rail's paint is the binary's answer (`drawer rail`): the theme's
// user-message background as Claude Code resolves it, a custom theme's
// overrides included — the module sees only the theme's name in the
// settings, the binary reads the theme files themselves. Asked once per
// theme name and kept; an edited custom theme is read again next session,
// as a picture's colours are. A binary without the door, or none, falls
// to the stock table in railHex.
const railAsked = new Map<string, Promise<string>>()

function railOnce($: EngineInterface, theme: string) {
  let p = railAsked.get(theme)
  if (p === undefined) {
    p = (async () => {
      try {
        const { exitCode, stdout } = await $.process.run([`${$.plugin.root}/scripts/drawer`, 'rail'], { timeoutMs: runMs })
        const hex = stdout.trim()
        if (exitCode === 0 && /^#[0-9a-fA-F]{6}$/.test(hex)) return hex
      } catch {
        // the stock table stands
      }
      return railHex(theme)
    })()
    railAsked.set(theme, p)
  }
  return p
}

// railHex is the stock table, for a binary without the -rail door or none
// in place: internal/theme's user-message backgrounds by stock name. A
// theme it cannot place is dark, as the binary reads it.
function railHex(theme: string): string {
  if (!theme.startsWith('light')) return '#373737'
  return theme.includes('daltonized') ? '#dcdcdc' : '#f0f0f0'
}

// listText draws the list door's rows: every span in its own style, a
// span with an address as a Link around its text.
function listText(ui: Elements['terminal'], el: Extract<Drawing, { kind: 'text' }>, top: number) {
  const { Box, Text, Link } = ui
  return (
    <Box flexDirection="column" marginTop={top}>
      {el.lines.map((line) => (
        <Text wrap="truncate-end">
          {!line || line.length === 0
            ? ' '
            : line.map((s) => {
                const style: { color?: string; dimColor?: boolean; bold?: boolean; italic?: boolean; strikethrough?: boolean } = {}
                if (s.c) style.color = s.c
                if (s.d) style.dimColor = true
                if (s.b) style.bold = true
                if (s.i) style.italic = true
                if (s.s) style.strikethrough = true
                const run = <Text {...style}>{s.t}</Text>
                return s.href === undefined ? run : <Link href={s.href}>{run}</Link>
              })}
        </Text>
      ))}
    </Box>
  )
}

// railsBlock draws one level the fallback way: its items as Markdown
// runs, each deeper level as a block of its own between them, all beside
// this level's stripe.
function railsBlock(ui: Elements['terminal'], lines: string[], top: number, hex: string): RenderChildren {
  const { Box, Markdown } = ui
  let base = 0
  for (const l of lines) {
    const mi = markerIndentOf(l)
    if (mi !== null) {
      base = mi
      break
    }
  }
  const deep = base + 2
  const kids: RenderChildren[] = []
  let run: string[] = []
  const flush = () => {
    while (run.length > 0 && trimSpace(run[0] ?? '') === '') run.shift()
    while (run.length > 0 && trimSpace(run[run.length - 1] ?? '') === '') run.pop()
    if (run.length > 0) kids.push(<Markdown text={run.join('\n')} />)
    run = []
  }
  const dedent = (l: string) => (leadingSpaces(l) >= base ? l.slice(base) : l.slice(leadingSpaces(l)))
  for (let i = 0; i < lines.length; ) {
    const l = lines[i] ?? ''
    const f = openerOf(l)
    if (f) {
      run.push(dedent(l))
      let k = i + 1
      while (k < lines.length && !closes(f, lines[k] ?? '')) run.push(dedent(lines[k] ?? '')), k++
      if (k < lines.length) run.push(dedent(lines[k] ?? '')), k++
      i = k
      continue
    }
    const mi = markerIndentOf(l)
    if (mi !== null && mi >= deep) {
      let j = i + 1
      while (j < lines.length) {
        const n = lines[j] ?? ''
        if (openerOf(n) && leadingSpaces(n) >= deep) {
          const k = (() => {
            const g = openerOf(n)
            let x = j + 1
            while (g && x < lines.length && !closes(g, lines[x] ?? '')) x++
            return x < lines.length ? x + 1 : lines.length
          })()
          j = k
          continue
        }
        if (trimSpace(n) === '') {
          j++
          continue
        }
        const ni = markerIndentOf(n)
        if (ni !== null ? ni < deep : leadingSpaces(n) < deep) break
        j++
      }
      flush()
      kids.push(railsBlock(ui, lines.slice(i, j), 0, hex))
      i = j
      continue
    }
    run.push(dedent(l))
    i++
  }
  flush()
  return (
    <Box flexDirection="row" marginTop={top}>
      <Box width={1} backgroundColor={hex} />
      <Box flexDirection="column" flexGrow={1} paddingLeft={1}>
        {kids}
      </Box>
    </Box>
  )
}

// cutListsSafe is cutLists held: a stretch the cutter chokes on is prose,
// and the reply still draws.
function cutListsSafe(text: string): Piece[] {
  try {
    return cutLists(text)
  } catch {
    return [{ prose: text }]
  }
}

// The bullet that opens a reply is Claude Code's, drawn with the first
// stretch of prose. A reply that opens with a graph has no prose there to
// carry it, and gets Claude Code's glyph from here: ⏺ on macOS, ● elsewhere.
let bullet: string | undefined

async function bulletOf($: EngineInterface) {
  if (bullet === undefined) {
    try {
      bullet = (await $.process.run(['uname', '-s'])).stdout.trim() === 'Darwin' ? '⏺' : '●'
    } catch {
      bullet = '●'
    }
  }
  return bullet
}

// picture is one drawing, standing where the display hook's would: at the
// text's own column, in the fence's indent, a row clear of the prose above.
function picture(ui: Elements['terminal'], el: Exclude<Drawing, { kind: 'none' }>, indent: number, top: number) {
  const { Box, Text, Image } = ui
  const pad = { paddingLeft: indent, marginTop: top }
  if (el.kind === 'image') {
    return (
      <Box {...pad}>
        <Image source={{ png: el.png }} columns={el.columns} rows={el.rows} alt={el.alt ?? ''} />
      </Box>
    )
  }
  return (
    <Box flexDirection="column" {...pad}>
      {el.lines.map((line) => (
        <Text wrap="truncate-end">
          {!line || line.length === 0
            ? ' '
            : line.map((s) => {
                const style: { color?: string; dimColor?: boolean } = {}
                if (s.c) style.color = s.c
                if (s.d) style.dimColor = true
                return <Text {...style}>{s.t}</Text>
              })}
        </Text>
      ))}
    </Box>
  )
}

export const register: Register = (on) => {
  on('ui.render', { component: 'AssistantMessage' }, async ($, e, next) => {
    if (e.surface !== 'terminal') return next(e)
    const text = e.props.text
    if (!text.includes('```') && !text.includes('~~~') && !anyMarker.test(text)) return next(e)
    const parts = split(text)

    const cols = e.viewport?.columns ?? 0
    const theme = String((await $.settings.read()).theme ?? '')
    const els = await Promise.all(parts.map((p) => (p.src === undefined ? null : drawOnce($, p.src, cols, p.indent ?? 0, theme, 'element', p.tag))))

    // A graph that will not draw is prose again, and so is a notice on a
    // fence the reply never closed: that is a reply cut off, not a graph
    // somebody got wrong.
    const blocks: ({ prose: string; el?: undefined } | { el: Exclude<Drawing, { kind: 'none' }>; indent: number })[] = []
    let prose: string[] = []
    parts.forEach((p, i) => {
      const el = els[i]
      if (!el || el.kind === 'none' || (el.notice && !p.closed)) {
        prose.push(p.raw)
        return
      }
      blocks.push({ prose: prose.join('\n') })
      blocks.push({ el, indent: p.indent ?? 0 })
      prose = []
    })
    blocks.push({ prose: prose.join('\n') })
    const cuts = blocks.map((b) => (b.el ? null : cutListsSafe(b.prose)))
    const anyList = cuts.some((c) => c !== null && c.some((p) => 'list' in p))
    if (!blocks.some((b) => b.el) && !anyList) return next(e)

    const ui = $.ui.resolve(e)
    const { Box, Text } = ui
    const body: RenderChildren[] = []
    let first = e.props.isFirstOfReply
    let opened = false // a bullet is on screen, so what follows stands in its column
    for (let bi = 0; bi < blocks.length; bi++) {
      const b = blocks[bi]
      if (b === undefined) continue
      if (b.el) {
        body.push(picture(ui, b.el, b.indent, body.length === 0 ? 0 : 1))
        continue
      }
      for (const p of cuts[bi] ?? []) {
        if ('list' in p) {
          const top = body.length === 0 ? 0 : 1
          const el = await drawOnce($, p.list.join('\n'), cols, 0, theme, 'list')
          if (el.kind === 'text') body.push(listText(ui, el, top))
          else body.push(railsBlock(ui, p.list, top, await railOnce($, theme)))
          continue
        }
        const stretch = p.prose.replace(/^(?:[ \t]*\n)+/, '').replace(/(?:\n[ \t]*)+$/, '')
        if (stretch.trim() === '') continue
        body.push(await next({ ...e, props: { ...e.props, text: stretch, isFirstOfReply: first && body.length === 0 } }))
        if (first && body.length === 1) opened = true
      }
    }

    if (!first) return <Box flexDirection="column">{body}</Box>
    if (opened) {
      return (
        <Box flexDirection="column">
          {body[0]}
          <Box flexDirection="column" paddingLeft={2}>
            {body.slice(1)}
          </Box>
        </Box>
      )
    }
    return (
      <Box flexDirection="row" alignItems="flex-start" marginTop={1}>
        <Box minWidth={2}>
          <Text color="text">{await bulletOf($)}</Text>
        </Box>
        <Box flexDirection="column">{body}</Box>
      </Box>
    )
  })
}

